def _parse(core):
    """core -> nested structure: list of parts; a part is a str or ('alt', [parts, ...], optional)."""
    pos = 0
    def seq(stop):
        nonlocal pos; out = []; lit = ""
        while pos < len(core) and core[pos] not in stop:
            ch = core[pos]
            if ch == "(":
                if lit: out.append(lit); lit = ""
                pos += 1; alts = [seq("|)")]
                while pos < len(core) and core[pos] == "|": pos += 1; alts.append(seq("|)"))
                pos += 1; opt = False
                if pos < len(core) and core[pos] == "?": opt = True; pos += 1
                out.append(("alt", alts, opt))
            elif pos + 1 < len(core) and core[pos + 1] == "?" and ch not in "|)":              # "x?" = optional single character (e.g. " ?" = optional space)
                if lit: out.append(lit); lit = ""
                out.append(("alt", [[ch], []], False)); pos += 2
            else: lit += ch; pos += 1
        if lit: out.append(lit)
        return out
    return seq("")


def _gen(parts, rnd):
    """one random realisation of a parsed grammar"""
    out = ""
    for p in parts:
        if isinstance(p, str): out += p
        else:
            _, alts, opt = p
            if opt and rnd.random() < 0.5: continue
            out += _gen(rnd.choice(alts), rnd)
    return out


def expand(core, rnd, cap=36):
    """cap distinct random realisations of a grammar with "(a|b|c)" groups (nested allowed) and "(x)?" optional parts."""
    core = re.sub(r"\(\.\{0,\d+\}\)", "", core); parts = _parse(core); out = []
    for _ in range(cap * 6):
        s = re.sub(r"\s+", " ", _gen(parts, rnd)).strip(" ,"); s = re.sub(r"\s+([?.,!])", r"", s)
        if s and s not in out: out.append(s)
        if len(out) >= cap: break
    return out


def held_out():
    s = set()
    for fn in ("heldout_dev.tsv", "heldout_dev2.tsv", "heldout_final.tsv"):
        p = os.path.join(HERE, "bench", fn)
        if os.path.exists(p):
            for l in open(p, encoding="utf-8"):
                if "\t" in l and not l.startswith("#"): s.add(re.sub(r"\W+", " ", l.split("\t", 1)[1].lower()).strip())
    return s


def build(seed=11):
    rnd = random.Random(seed); out = []; hold = held_out()
    for route, cores in G.items():
        seen = set()
        for core in cores:
            for q in expand(core, rnd):
                for lead in rnd.sample(LEAD, 2):
                    qq = (lead + q).strip(); k = re.sub(r"\W+", " ", qq.lower()).strip()
                    if k in seen or k in hold or len(qq) < 5 or "  " in qq: continue
                    seen.add(k); out.append((route, qq))
    return out


if __name__ == "__main__":
    rows = build(); path = os.path.join(HERE, "bench", "everyday_grammar.tsv")
    with open(path, "w", encoding="utf-8") as f:
        f.write("# route<TAB>question - generated by tools_everyday_grammar.py (do not edit by hand)\n")
        for r, q in rows: f.write(f"{r}\t{q}\n")
    from collections import Counter
    c = Counter(r for r, _ in rows); print(len(rows), "examples over", len(c), "routes; min/max per route", min(c.values()), max(c.values()))
